CREATE TABLE institution(id BIGINT PRIMARY KEY,code VARCHAR(64),name VARCHAR(100),type VARCHAR(20),status INT);
INSERT INTO institution VALUES(1,'QA1','虚构本院','INTERNAL',1),(2,'QA2','虚构他院','INTERNAL',1);
CREATE TABLE sys_dept(id BIGINT PRIMARY KEY,institution_id BIGINT,dept_name VARCHAR(100),dept_code VARCHAR(64),parent_id BIGINT,sort_order INT,contact_person VARCHAR(64),contact_phone VARCHAR(32),status INT,remark VARCHAR(200),is_deleted INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP);
