CREATE TABLE sys_user(id BIGINT PRIMARY KEY,institution_id BIGINT,username VARCHAR(64),password VARCHAR(100),real_name VARCHAR(100),role VARCHAR(32),dept_id BIGINT,phone VARCHAR(32),email VARCHAR(100),status INT,is_deleted INT DEFAULT 0,user_code VARCHAR(64),created_at TIMESTAMP,updated_at TIMESTAMP);
