CREATE TABLE warehouse(id BIGINT PRIMARY KEY,institution_id BIGINT,name VARCHAR(100),code VARCHAR(64),level INT,parent_id BIGINT,dept_id BIGINT,location_code VARCHAR(64),location VARCHAR(200),contact_person VARCHAR(64),contact_phone VARCHAR(32),sort_order INT,status INT,remark VARCHAR(200),is_active BOOLEAN,created_at TIMESTAMP,updated_at TIMESTAMP);
