CREATE TABLE reagent_catalog(id BIGINT PRIMARY KEY,institution_id BIGINT,his_code VARCHAR(64),generic_name VARCHAR(200),material_type VARCHAR(32),manufacturer VARCHAR(128),distributor VARCHAR(128),specification VARCHAR(128),unit VARCHAR(32),storage_condition VARCHAR(128),test_groups VARCHAR(200),udi_di VARCHAR(128),gtin VARCHAR(64),insurance_code VARCHAR(64),is_insurance_payment INT DEFAULT 0,enable_unique_code INT DEFAULT 0,registration_cert_no VARCHAR(128),detection_method VARCHAR(100),tests_per_kit INT,price_per_unit DECIMAL(12,2),stability_days_after_open INT,lead_time_days INT,device_bind_mode VARCHAR(32),is_volume_based INT DEFAULT 0,volume_type VARCHAR(64),insurance_payment_type VARCHAR(64),is_chargeable INT DEFAULT 0,charge_code VARCHAR(64),approval_status VARCHAR(32),is_deleted INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP);
INSERT INTO reagent_catalog(id,institution_id,his_code,generic_name,material_type,manufacturer,distributor,unit,price_per_unit,device_bind_mode,approval_status,stability_days_after_open) VALUES(1,1,'QA-FLEX','虚构不需仪器试剂','REAGENT','QA厂家','QA供应商','盒',10,'FLEXIBLE','APPROVED',30),(2,1,'QA-FORCE','虚构需仪器试剂','REAGENT','QA厂家','QA供应商','盒',20,'FORCE','APPROVED',30),(3,2,'QA-FOREIGN','他院虚构目录','REAGENT','QA','QA','盒',10,'FLEXIBLE','APPROVED',30);
CREATE TABLE reagent_batch(id BIGINT PRIMARY KEY,institution_id BIGINT,batch_no VARCHAR(64),reagent_id BIGINT,material_type VARCHAR(32),udi_di VARCHAR(128),udi_pi VARCHAR(128),manufacture_date DATE,expiry_date DATE,open_date DATE,open_expiry_date DATE,stock DECIMAL(10,2),unit VARCHAR(32),unit_price DECIMAL(12,2),avg_cost DECIMAL(12,2),udi_status VARCHAR(32),warehouse_id BIGINT,location_code VARCHAR(64),inventory_generation INT DEFAULT 0,origin_purchase_order_item_id BIGINT,settlement_mode VARCHAR(32),version INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(institution_id,reagent_id,batch_no,warehouse_id,inventory_generation));
CREATE TABLE device(id BIGINT PRIMARY KEY,institution_id BIGINT,dept_id BIGINT,name VARCHAR(100),device_code VARCHAR(64),model VARCHAR(64),manufacturer VARCHAR(100),location_id BIGINT,is_active BOOLEAN,last_calibration_date DATE,next_calibration_date DATE,created_at TIMESTAMP,updated_at TIMESTAMP);
INSERT INTO device(id,institution_id,dept_id,name,device_code,location_id,is_active) VALUES(301,1,11,'虚构仪器','DEV301',102,TRUE),(302,1,12,'其他科室仪器','DEV302',103,TRUE),(401,2,21,'他院仪器','DEV401',202,TRUE);
CREATE TABLE device_batch_load(id BIGINT PRIMARY KEY,institution_id BIGINT,device_id BIGINT,batch_id BIGINT,batch_no VARCHAR(64),reagent_id BIGINT,operator_id BIGINT,load_time TIMESTAMP,unload_time TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE purchase_order(id BIGINT PRIMARY KEY,institution_id BIGINT,po_no VARCHAR(64),supplier_id INT,source_type VARCHAR(32),shortage_order_id BIGINT,req_id BIGINT,acceptance_method VARCHAR(32),settlement_mode VARCHAR(32),total_amount DECIMAL(12,2),status VARCHAR(32),order_date DATE,expected_arrival DATE,received_quantity DECIMAL(10,2),created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(institution_id,po_no));
CREATE TABLE purchase_order_item(id BIGINT PRIMARY KEY,institution_id BIGINT,po_id BIGINT,line_no INT,reagent_id BIGINT,supplier_id INT,material_type VARCHAR(32),order_quantity DECIMAL(10,2),unit_price DECIMAL(12,2),amount DECIMAL(12,2),received_quantity DECIMAL(10,2),version INT DEFAULT 0,created_at TIMESTAMP);
CREATE TABLE purchase_requisition(id BIGINT PRIMARY KEY,institution_id BIGINT,req_no VARCHAR(64),from_dept_id BIGINT,to_warehouse_id BIGINT,applicant_id BIGINT,urgency VARCHAR(32),status VARCHAR(32),reviewer_id BIGINT,review_time TIMESTAMP,review_comment VARCHAR(500),remark VARCHAR(500),received_at TIMESTAMP,research_project_id BIGINT,research_project_name VARCHAR(200),created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(institution_id,req_no));
CREATE TABLE purchase_requisition_item(id BIGINT PRIMARY KEY,institution_id BIGINT,req_id BIGINT,line_no INT,reagent_id BIGINT,specification VARCHAR(128),qty_requested DECIMAL(10,2),stock_on_hand DECIMAL(10,2),qty_fulfilled DECIMAL(10,2),qty_shortage DECIMAL(10,2),unit_price DECIMAL(12,2),amount DECIMAL(12,2),group_id INT,shortage_order_id BIGINT,created_at TIMESTAMP);
CREATE TABLE consumption_record(id BIGINT PRIMARY KEY,institution_id BIGINT,record_type VARCHAR(32),batch_no VARCHAR(64),batch_id BIGINT,purchase_order_item_id BIGINT,settlement_mode VARCHAR(32),requisition_item_id BIGINT,reagent_id BIGINT,material_type VARCHAR(32),device_id BIGINT,quantity DECIMAL(10,2),unit VARCHAR(32),unit_price DECIMAL(12,2),amount DECIMAL(12,2),purpose VARCHAR(32),warehouse_id BIGINT,requisition_id BIGINT,from_warehouse_id BIGINT,operator_id BIGINT,remark VARCHAR(500),occurred_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE requisition_transfer_receipt(transfer_record_id BIGINT,institution_id BIGINT,target_batch_id BIGINT,received_by BIGINT,received_at TIMESTAMP,PRIMARY KEY(institution_id,transfer_record_id));
CREATE TABLE settlement_record(id BIGINT PRIMARY KEY,institution_id BIGINT,settlement_no VARCHAR(64),settlement_type VARCHAR(32),source_id BIGINT,source_item_id BIGINT,source_item_kind VARCHAR(32),source_no VARCHAR(100),batch_no VARCHAR(64),reagent_id BIGINT,quantity DECIMAL(10,2),unit_price DECIMAL(12,2),amount DECIMAL(12,2),status VARCHAR(32),from_dept_id BIGINT,settled_by BIGINT,settled_at TIMESTAMP,reversed_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(institution_id,settlement_type,source_id,source_item_kind,source_item_id));
CREATE TABLE settlement_event(id BIGINT AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT,settlement_id BIGINT NOT NULL,from_status VARCHAR(32),to_status VARCHAR(32),reason VARCHAR(500),operator_id BIGINT,operator_name VARCHAR(100),created_at TIMESTAMP,FOREIGN KEY(settlement_id) REFERENCES settlement_record(id));
CREATE TABLE udi_status_log(id BIGINT PRIMARY KEY,institution_id BIGINT,batch_no VARCHAR(64),from_status VARCHAR(32),to_status VARCHAR(32),operator_id BIGINT,operator_name VARCHAR(100),remark VARCHAR(500),occurred_at TIMESTAMP,created_at TIMESTAMP);
CREATE TABLE udi_unique_code(id BIGINT PRIMARY KEY,institution_id BIGINT,unique_code VARCHAR(100),batch_id BIGINT,reagent_id BIGINT,batch_no VARCHAR(64),udi_di VARCHAR(128),status VARCHAR(32),created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(institution_id,unique_code));
CREATE TABLE udi_unique_code_seq(institution_id BIGINT,date_key VARCHAR(32),current_seq BIGINT,PRIMARY KEY(institution_id,date_key));
